//! KPK (king + pawn vs king) win/draw bitbase, generated by retrograde
//! analysis on first use (a few ms in release builds).
//!
//! Positions are normalised so the pawn is White's and stands on files a-d
//! (files e-h are mirrored). The index is
//! `stm * 24*64*64 + bk * 24*64 + wk * 24 + pawn_idx`, with
//! `pawn_idx = file + 4 * (rank - 1)` for ranks 2..7 (rank 0-based 1..6).
//!
//! Classification follows the classic scheme (also used by Stockfish):
//! - invalid: kings on the same/adjacent squares, a king on the pawn square,
//!   or White to move with the black king attacked by the pawn;
//! - immediate win: White to move, pawn on the 7th, the promotion square is
//!   free of the white king and either out of the black king's reach or
//!   protected by the white king;
//! - immediate draw: Black to move and stalemated, or able to take an
//!   undefended pawn;
//! - otherwise White to move wins if some move reaches a won position, Black to
//!   move loses if every legal move reaches one. Iterated to a fixpoint; what
//!   is not proven won is a draw.

use std::sync::OnceLock;

const PAWN_SQS: usize = 24;
const MAX_INDEX: usize = 2 * 64 * 64 * PAWN_SQS;

/// Bit `i` set = position `i` is a win for the side with the pawn.
static BITBASE: OnceLock<Vec<u64>> = OnceLock::new();

#[inline]
fn index(white_to_move: bool, wk: u8, bk: u8, psq: u8) -> usize {
    let file = (psq % 8) as usize;
    let rank = (psq / 8) as usize;
    debug_assert!(file < 4 && (1..=6).contains(&rank));
    let pidx = file + 4 * (rank - 1);
    (if white_to_move { 0 } else { 1 }) * 64 * 64 * PAWN_SQS
        + bk as usize * 64 * PAWN_SQS
        + wk as usize * PAWN_SQS
        + pidx
}

fn king_attacks(sq: u8) -> u64 {
    let b = 1u64 << sq;
    const NOT_A: u64 = !0x0101_0101_0101_0101;
    const NOT_H: u64 = !0x8080_8080_8080_8080;
    let lr = ((b << 1) & NOT_A) | ((b >> 1) & NOT_H);
    let row = b | lr;
    (lr | (row << 8) | (row >> 8)) & !b
}

/// Squares attacked by a white pawn on `sq`.
fn pawn_attacks(sq: u8) -> u64 {
    let b = 1u64 << sq;
    const NOT_A: u64 = !0x0101_0101_0101_0101;
    const NOT_H: u64 = !0x8080_8080_8080_8080;
    ((b << 7) & NOT_H) | ((b << 9) & NOT_A)
}

fn distance(a: u8, b: u8) -> i32 {
    let df = ((a % 8) as i32 - (b % 8) as i32).abs();
    let dr = ((a / 8) as i32 - (b / 8) as i32).abs();
    df.max(dr)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum State {
    Invalid,
    Unknown,
    Win,
    Draw,
}

fn initial(white_to_move: bool, wk: u8, bk: u8, psq: u8) -> State {
    if distance(wk, bk) <= 1
        || wk == psq
        || bk == psq
        || (white_to_move && pawn_attacks(psq) & (1u64 << bk) != 0)
    {
        return State::Invalid;
    }
    if white_to_move {
        let promo = psq + 8;
        if psq / 8 == 6 && wk != promo && (distance(bk, promo) > 1 || distance(wk, promo) == 1) {
            return State::Win;
        }
    } else {
        let free = king_attacks(bk) & !(king_attacks(wk) | pawn_attacks(psq));
        if free == 0 {
            // No legal king move; in check would be mate, which K+P cannot deliver.
            return if pawn_attacks(psq) & (1u64 << bk) != 0 { State::Win } else { State::Draw };
        }
        if king_attacks(bk) & (1u64 << psq) & !king_attacks(wk) != 0 {
            return State::Draw;
        }
    }
    State::Unknown
}

fn generate() -> Vec<u64> {
    let mut db = vec![State::Invalid; MAX_INDEX];
    let mut positions = Vec::with_capacity(MAX_INDEX);
    for stm in [true, false] {
        for bk in 0..64u8 {
            for wk in 0..64u8 {
                for rank in 1..=6u8 {
                    for file in 0..4u8 {
                        let psq = rank * 8 + file;
                        let idx = index(stm, wk, bk, psq);
                        let st = initial(stm, wk, bk, psq);
                        db[idx] = st;
                        if st == State::Unknown {
                            positions.push((idx as u32, stm, wk, bk, psq));
                        }
                    }
                }
            }
        }
    }

    // Least fixpoint of "won": keep re-scanning the unresolved positions.
    let mut changed = true;
    while changed {
        changed = false;
        positions.retain(|&(idx, stm, wk, bk, psq)| {
            let won = if stm {
                // White: any king move or pawn push into a won (Black-to-move) position.
                let mut targets = king_attacks(wk) & !king_attacks(bk) & !(1u64 << psq);
                let mut won = false;
                while targets != 0 && !won {
                    let to = targets.trailing_zeros() as u8;
                    targets &= targets - 1;
                    won = db[index(false, to, bk, psq)] == State::Win;
                }
                if !won && psq / 8 < 6 {
                    let one = psq + 8;
                    if one != wk && one != bk {
                        won = db[index(false, wk, bk, one)] == State::Win;
                        let two = psq + 16;
                        if !won && psq / 8 == 1 && two != wk && two != bk {
                            won = db[index(false, wk, bk, two)] == State::Win;
                        }
                    }
                }
                won
            } else {
                // Black: every legal king move must reach a won position.
                let mut targets = king_attacks(bk) & !king_attacks(wk) & !pawn_attacks(psq);
                let mut all_won = true;
                while targets != 0 && all_won {
                    let to = targets.trailing_zeros() as u8;
                    targets &= targets - 1;
                    // Taking a defended pawn is illegal (excluded via king_attacks(wk));
                    // taking an undefended one was an immediate draw.
                    all_won = to != psq && db[index(true, wk, to, psq)] == State::Win;
                }
                all_won
            };
            if won {
                db[idx as usize] = State::Win;
                changed = true;
                false
            } else {
                true
            }
        });
    }
    for &(idx, ..) in &positions {
        db[idx as usize] = State::Draw;
    }

    let mut bits = vec![0u64; MAX_INDEX / 64];
    for (i, &st) in db.iter().enumerate() {
        if st == State::Win {
            bits[i / 64] |= 1u64 << (i % 64);
        }
    }
    bits
}

/// Builds the bitbase now (so the first probe during a timed search is free).
pub(crate) fn init() {
    BITBASE.get_or_init(generate);
}

/// True if the side owning the pawn wins. Squares are given with the pawn
/// owner as White: `strong_king`, `weak_king`, `pawn` (rank 2..7), and
/// `strong_to_move` = the pawn owner is to move. The position must be legal.
pub(crate) fn probe(strong_to_move: bool, strong_king: u8, weak_king: u8, pawn: u8) -> bool {
    let (mut wk, mut bk, mut psq) = (strong_king, weak_king, pawn);
    if psq % 8 >= 4 {
        wk ^= 7;
        bk ^= 7;
        psq ^= 7;
    }
    let bits = BITBASE.get_or_init(generate);
    let i = index(strong_to_move, wk, bk, psq);
    bits[i / 64] >> (i % 64) & 1 != 0
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::movegen::parse_square;

    fn sq(s: &str) -> u8 {
        parse_square(s).unwrap()
    }

    #[test]
    fn win_count_matches_reference() {
        // Wins over both sides to move in the 2 x 24 x 64 x 64 index; the
        // same count Stockfish's identically-indexed KPK bitbase asserts.
        let bits = BITBASE.get_or_init(generate);
        let wins: u32 = bits.iter().map(|w| w.count_ones()).sum();
        assert_eq!(wins, 111_282);
    }

    #[test]
    fn known_positions() {
        // (white to move, wk, bk, pawn, win)
        let cases = [
            // Key-square win: king in front of the pawn on the 6th.
            (true, "e6", "e8", "e5", true),
            (false, "e6", "e8", "e5", true),
            // King directly in front of the pawn: the opposition decides.
            (true, "e5", "e7", "e4", false),
            (false, "e5", "e7", "e4", true),
            (true, "e4", "e6", "e3", false), // Black has the opposition.
            (false, "e4", "e6", "e3", true), // White has the opposition.
            // Rook pawn with the defender in the corner: draw.
            (true, "b6", "a8", "a5", false),
            (true, "h6", "h8", "h5", false),
            // Pawn too far for the defending king: rule of the square.
            (true, "a1", "h5", "d5", true),
            (false, "a1", "h5", "d5", false),
            // Defending king blockades the pawn on the 8th: draw.
            (true, "e5", "e8", "e6", false),
            (false, "e5", "e8", "e6", false), // ...Ke7! keeps the blockade.
            // Undefended pawn about to be taken.
            (false, "a1", "d4", "e5", false),
        ];
        for (stm, wk, bk, p, win) in cases {
            assert_eq!(probe(stm, sq(wk), sq(bk), sq(p)), win, "{stm} K{wk} k{bk} P{p}");
        }
    }

    #[test]
    fn file_mirror_is_symmetric() {
        for wk in 0..64u8 {
            for bk in 0..64u8 {
                for psq in 8..56u8 {
                    let m = if psq % 8 >= 4 { 7 } else { 0 };
                    if initial(true, wk ^ m, bk ^ m, psq ^ m) == State::Invalid {
                        continue;
                    }
                    assert_eq!(probe(true, wk, bk, psq), probe(true, wk ^ 7, bk ^ 7, psq ^ 7));
                }
            }
        }
    }
}
